import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { HEARTBEAT_MS, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, nowIso, type JobRow } from './jobs.ts';

const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const stmts = {
  // An interrupted attempt keeps its `attempts` count (it was started). It is recorded in
  // `interrupted_attempts` so it does not use up the retry budget.
  recoverRunning: db.prepare(
    `UPDATE jobs SET status = 'queued', interrupted_attempts = interrupted_attempts + 1, progress_completed = 0, run_after = 0, updated_at = ?
     WHERE status = 'running'`,
  ),
  requeueInterrupted: db.prepare(
    `UPDATE jobs SET status = 'queued', interrupted_attempts = interrupted_attempts + 1, progress_completed = 0, run_after = 0, updated_at = ?
     WHERE id = ?`,
  ),
  nextDue: db.prepare(`SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY rowid LIMIT 1`),
  setState: db.prepare(
    `UPDATE jobs SET status = ?, attempts = ?, progress_completed = 0, result_output = NULL, error = ?, run_after = ?, updated_at = ?
     WHERE id = ?`,
  ),
  progress: db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`),
  complete: db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ),
  heartbeat: db.prepare(
    `INSERT INTO heartbeats (name, seen_at) VALUES ('worker', ?) ON CONFLICT (name) DO UPDATE SET seen_at = excluded.seen_at`,
  ),
};

function transaction<T>(fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let committed = false;
  try {
    const result = fn();
    db.exec('COMMIT');
    committed = true;
    return result;
  } finally {
    if (!committed) db.exec('ROLLBACK');
  }
}

let lastHeartbeat = 0;
function beat(force = false): void {
  const now = Date.now();
  if (force || now - lastHeartbeat >= HEARTBEAT_MS) {
    stmts.heartbeat.run(now);
    lastHeartbeat = now;
  }
}

type Claim = { kind: 'idle' } | { kind: 'attempt-failed' } | { kind: 'run'; job: JobRow };

/**
 * Takes the oldest due job and starts its next attempt in one transaction. A simulated failure
 * is decided here too, so a crash never leaves a job half-updated.
 */
function claimNext(): Claim {
  return transaction<Claim>(() => {
    const job = stmts.nextDue.get(Date.now()) as unknown as JobRow | undefined;
    if (!job) return { kind: 'idle' };

    const attempts = job.attempts + 1;
    // Logical attempt number: an interrupted attempt is retried under the same number.
    const attempt = attempts - job.interrupted_attempts;
    const now = nowIso();
    if (attempt <= job.fail_attempts) {
      // Simulated transient failure, before any progress.
      if (attempt < MAX_ATTEMPTS) {
        stmts.setState.run('queued', attempts, null, Date.now() + RETRY_DELAY_MS, now, job.id);
      } else {
        stmts.setState.run('failed', attempts, TRANSIENT_ERROR, 0, now, job.id);
      }
      return { kind: 'attempt-failed' };
    }
    stmts.setState.run('running', attempts, null, 0, now, job.id);
    return { kind: 'run', job: { ...job, attempts } };
  });
}

/** Runs the steps of a started attempt. Returns early, leaving the job queued, if the worker is asked to stop. */
async function processJob(job: JobRow): Promise<void> {
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      transaction(() => stmts.requeueInterrupted.run(nowIso(), job.id));
      return;
    }
    stmts.progress.run(step, nowIso(), job.id);
    beat();
  }
  stmts.complete.run(job.steps, job.input.toUpperCase(), nowIso(), job.id);
}

transaction(() => stmts.recoverRunning.run(nowIso()));
beat(true);
console.log('worker started');

while (!stopping) {
  beat();
  const claim = claimNext();
  if (claim.kind === 'idle') {
    await sleep(IDLE_POLL_MS);
  } else if (claim.kind === 'run') {
    await processJob(claim.job);
  }
}

// Marks the worker as down straight away rather than waiting for the heartbeat to go stale.
stmts.heartbeat.run(0);
db.close();
console.log('worker stopped');

