import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { HEARTBEAT_MS, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, nowIso, type JobRow } from './jobs.ts';

const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const stmts = {
  // An attempt interrupted by a crash or shutdown did not finish, so it is undone and run again
  // under the same attempt number.
  recoverRunning: db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ?
     WHERE status = 'running'`,
  ),
  requeueInterrupted: db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ?
     WHERE id = ?`,
  ),
  nextDue: db.prepare(`SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY rowid LIMIT 1`),
  startAttempt: db.prepare(`UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ?`),
  progress: db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`),
  complete: db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ),
  scheduleRetry: db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, error = NULL, run_after = ?, updated_at = ? WHERE id = ?`,
  ),
  fail: db.prepare(
    `UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ? WHERE id = ?`,
  ),
  heartbeat: db.prepare(
    `INSERT INTO heartbeats (name, seen_at) VALUES ('worker', ?) ON CONFLICT (name) DO UPDATE SET seen_at = excluded.seen_at`,
  ),
};

let lastHeartbeat = 0;
function beat(force = false): void {
  const now = Date.now();
  if (force || now - lastHeartbeat >= HEARTBEAT_MS) {
    stmts.heartbeat.run(now);
    lastHeartbeat = now;
  }
}

/** Runs one attempt. Returns early, leaving the job queued, if the worker is asked to stop. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts + 1;
  stmts.startAttempt.run(attempt, nowIso(), job.id);

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: it happens before any progress is made.
    if (attempt < MAX_ATTEMPTS) stmts.scheduleRetry.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    else stmts.fail.run(TRANSIENT_ERROR, nowIso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      stmts.requeueInterrupted.run(nowIso(), job.id);
      return;
    }
    stmts.progress.run(step, nowIso(), job.id);
    beat();
  }
  stmts.complete.run(job.steps, job.input.toUpperCase(), nowIso(), job.id);
}

stmts.recoverRunning.run(nowIso());
beat(true);
console.log('worker started');

while (!stopping) {
  beat();
  const job = stmts.nextDue.get(Date.now()) as unknown as JobRow | undefined;
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(job);
}

// Marks the worker as down straight away rather than waiting for the heartbeat to go stale.
stmts.heartbeat.run(0);
db.close();
console.log('worker stopped');
